// --- Flag rendering helpers ---

// Sun of May rays for Argentina
const sunRays = Array.from({ length: 12 }, (_, i) => {
  const angle = (i * 30) * Math.PI / 180;
  const x1 = (37 + 10 * Math.sin(angle)).toFixed(1);
  const y1 = (37 - 10 * Math.cos(angle)).toFixed(1);
  const x2 = (37 + 16 * Math.sin(angle)).toFixed(1);
  const y2 = (37 - 16 * Math.cos(angle)).toFixed(1);
  return <line key={i} x1={x1} y1={y1} x2={x2} y2={y2} stroke="#F6B40E" strokeWidth="2.5" />;
});

// USA: 13 stripes
const usaStripes = Array.from({ length: 13 }, (_, i) =>
  i % 2 === 0 ? <rect key={i} y={(i * 75 / 13).toFixed(2)} width="75" height={(75 / 13).toFixed(2)} fill="#BF0A30" /> : null
);
// USA: 5 rows of stars (6-5-6-5-6)
const usaStars = Array.from({ length: 5 }, (_, row) => {
  const cols = row % 2 === 0 ? 6 : 5;
  const xOff = row % 2 === 0 ? 3 : 6;
  return Array.from({ length: cols }, (_, col) => {
    const x = xOff + col * 5, y = 4 + row * 7;
    return <polygon key={`${row}-${col}`} points={`${x},${y-2} ${x+0.7},${y-0.6} ${x+2},${y-0.6} ${x+1},${y+0.5} ${x+1.4},${y+2} ${x},${y+1.2} ${x-1.4},${y+2} ${x-1},${y+0.5} ${x-2},${y-0.6} ${x-0.7},${y-0.6}`} fill="white" />;
  });
});

