// Seam color per nation (lighter on white/dark backgrounds)
const SEAM_COLORS = {
  germany:    'rgba(255,255,255,0.2)',
  australia:  'rgba(255,255,255,0.2)',
  scotland:   'rgba(255,255,255,0.2)',
  saudi:      'rgba(255,255,255,0.22)',
  netherlands:'rgba(255,255,255,0.22)',
  japan:      'rgba(0,0,0,0.15)',
  england:    'rgba(0,0,0,0.15)',
  southkorea: 'rgba(0,0,0,0.15)',
};

export default function SoccerBallKit({ kitId, size = 56 }) {
  const flag = FLAGS[kitId];
  const seamColor = SEAM_COLORS[kitId] || 'rgba(0,0,0,0.22)';
  const uid = `clip-${kitId}`;

  if (!flag) return null;

  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 75 75"
      xmlns="http://www.w3.org/2000/svg"
      style={{ display: 'block', flexShrink: 0 }}
    >
      <defs>
        <clipPath id={uid}>
          <circle cx="37.4" cy="37.4" r="35.6" />
        </clipPath>
      </defs>
      <g clipPath={`url(#${uid})`}>{flag}</g>
      <path d={SEAM_PATH} fill={seamColor} fillRule="evenodd" />
    </svg>
  );
}
